INSERT INTO DimCompany (SK_CompanyID, CompanyID, Status, Name, Industry, SPrating, isLowGrade, CEO, Description, FoundingDate, AddressLine1, AddressLine2, PostalCode, City, StateProv, Country, IsCurrent, BatchID, EffectiveDate, EndDate) SELECT ROW_NUMBER() OVER (ORDER BY CompanyID, EffectiveDate) AS SK_CompanyID, CompanyID, Status, Name, Industry, SPrating, isLowGrade, CEO, Description, FoundingDate, AddressLine1, AddressLine2, PostalCode, City, StateProv, Country, CASE WHEN LEAD(EffectiveDate) OVER (PARTITION BY CompanyID ORDER BY EffectiveDate ASC) IS NULL THEN TRUE ELSE FALSE END AS IsCurrent, 1 AS BatchID, EffectiveDate, COALESCE(LEAD(EffectiveDate) OVER (PARTITION BY CompanyID ORDER BY EffectiveDate ASC), CAST('9999-12-31' AS DATE)) AS EndDate FROM (SELECT CIK AS CompanyID, CompanyName AS Name, SPrating, CEOname AS CEO, Description, CAST(TRY_STRPTIME(FoundingDate, '%Y%m%d') AS DATE) AS FoundingDate, AddrLine1 AS AddressLine1, AddrLine2 AS AddressLine2, PostalCode, City, StateProvince AS StateProv, Country, S.ST_NAME AS Status, I.IN_NAME AS Industry, (CASE WHEN SPrating LIKE 'A%' OR SPrating LIKE 'BBB%' THEN FALSE ELSE TRUE END) AS isLowGrade, STRPTIME(PTS, '%Y%m%d-%H%M%S') AS EffectiveDate FROM Source.FinwireCMP AS CMP, Source.StatusType AS S, Source.Industry AS I WHERE CMP.Status = S.ST_ID AND CMP.IndustryID = I.IN_ID) AS c;
